<?php $h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<!doctype html><html lang="it"><head><meta charset="utf-8"><title>Registro cancellazioni sessioni</title></head><body class="ui-page"><header class="ui-page-heading" data-page-heading><span data-icon="book" aria-hidden="true"></span><div><h1>Registro cancellazioni</h1><p>Traccia permanente delle sessioni rimosse dall’archivio.</p></div></header><div class="media-admin-toolbar"><a class="action-btn" data-icon="back" href="/sessione/viewlog.php">Torna alle sessioni</a></div><div class="ui-table-scroll"><table class="ui-data-table"><thead><tr><th>Sessione</th><th>Luogo</th><th>Cancellata da</th><th>Data</th></tr></thead><tbody><?php foreach($deletions as $entry): ?><tr><td><strong><?=$h($entry['session_title'])?></strong><small class="ui-cell-meta">#<?=(int)$entry['session_id']?></small></td><td><?=$h($entry['chat_key'])?></td><td><?=$h($entry['admin_name'])?> <small>(ID <?=(int)$entry['deleted_by']?>)</small></td><td><?=$h(FormatTimestamp((int)$entry['deleted_at']))?></td></tr><?php endforeach; ?><?php if(!$deletions): ?><tr><td colspan="4" class="ui-empty">Nessuna sessione cancellata.</td></tr><?php endif; ?></tbody></table></div></body></html>
